"""Highest version in a list satisfying an npm-style range. See task.md."""

from __future__ import annotations

import operator
import re
from typing import NamedTuple


class RangeError(ValueError):
    """Raised for malformed range expressions and malformed versions."""


_NUM = r"(?:0|[1-9][0-9]*)"
_PRE_ID = r"(?:0|[1-9][0-9]*|[0-9]*[A-Za-z-][0-9A-Za-z-]*)"
_BUILD_ID = r"[0-9A-Za-z-]+"
_FULL = re.compile(
    rf"(?P<major>{_NUM})\.(?P<minor>{_NUM})\.(?P<patch>{_NUM})"
    rf"(?:-(?P<pre>{_PRE_ID}(?:\.{_PRE_ID})*))?"
    rf"(?:\+(?P<build>{_BUILD_ID}(?:\.{_BUILD_ID})*))?"
)
_WILDCARDS = ("x", "X", "*")
_OPERATORS = (">=", "<=", ">", "<", "=", "^", "~")
_COMPARE = {
    "=": operator.eq,
    ">": operator.gt,
    ">=": operator.ge,
    "<": operator.lt,
    "<=": operator.le,
}


class _Version(NamedTuple):
    major: int
    minor: int
    patch: int
    pre: tuple[str, ...]

    @property
    def core(self) -> tuple[int, int, int]:
        return (self.major, self.minor, self.patch)


class _Primitive(NamedTuple):
    op: str
    version: _Version


_ZERO = _Version(0, 0, 0, ())


def _parse_full(text: str) -> _Version | None:
    match = _FULL.fullmatch(text)
    if match is None:
        return None
    pre = tuple(match.group("pre").split(".")) if match.group("pre") else ()
    return _Version(
        int(match.group("major")),
        int(match.group("minor")),
        int(match.group("patch")),
        pre,
    )


def _parse_version(text: str) -> _Version:
    version = _parse_full(text)
    if version is None:
        raise RangeError(f"malformed version: {text!r}")
    return version


def _precedence(version: _Version) -> tuple:
    if not version.pre:
        return (*version.core, 1, ())
    return (*version.core, 0, tuple(_identifier_key(i) for i in version.pre))


def _identifier_key(identifier: str) -> tuple:
    if identifier.isdigit():
        return (0, int(identifier), "")
    return (1, 0, identifier)


def _parse_partial(body: str) -> tuple[list[int], _Version | None]:
    """Return the specified leading components and the full version if fully given."""
    full = _parse_full(body)
    if full is not None:
        return list(full.core), full
    if "-" in body or "+" in body:
        raise RangeError(f"suffix requires a full version: {body!r}")
    parts = body.split(".")
    if len(parts) > 3:
        raise RangeError(f"malformed version: {body!r}")
    nums: list[int] = []
    wildcard = False
    for part in parts:
        if part in _WILDCARDS:
            wildcard = True
        elif wildcard or re.fullmatch(_NUM, part) is None:
            raise RangeError(f"malformed version: {body!r}")
        else:
            nums.append(int(part))
    return nums, None


def _complete(nums: list[int], full: _Version | None) -> _Version:
    if full is not None:
        return full
    return _Version(*nums, *([0] * (3 - len(nums))), ())


def _bump(nums: list[int], index: int) -> _Version:
    bumped = nums[:index] + [nums[index] + 1]
    return _Version(*bumped, *([0] * (3 - len(bumped))), ())


def _caret_upper(nums: list[int]) -> _Version:
    index = next((i for i, n in enumerate(nums) if n != 0), len(nums) - 1)
    return _bump(nums, index)


def _tilde_upper(nums: list[int]) -> _Version:
    return _bump(nums, 1 if len(nums) >= 2 else 0)


def _desugar(token: str) -> list[_Primitive]:
    op = next((o for o in _OPERATORS if token.startswith(o)), "")
    body = token[len(op):]
    nums, full = _parse_partial(body)
    if op in (">", ">=", "<", "<="):
        if full is None:
            raise RangeError(f"comparator requires a full version: {token!r}")
        return [_Primitive(op, full)]
    if op in ("^", "~"):
        if not nums:
            raise RangeError(f"comparator requires a major version: {token!r}")
        upper = _caret_upper(nums) if op == "^" else _tilde_upper(nums)
        return [_Primitive(">=", _complete(nums, full)), _Primitive("<", upper)]
    if not nums:
        return [_Primitive(">=", _ZERO)]
    if full is not None:
        return [_Primitive("=", full)]
    return [
        _Primitive(">=", _complete(nums, None)),
        _Primitive("<", _bump(nums, len(nums) - 1)),
    ]


def _hyphen(low: str, high: str) -> list[_Primitive]:
    low_nums, low_full = _parse_partial(low)
    high_nums, high_full = _parse_partial(high)
    if not low_nums or not high_nums:
        raise RangeError(f"hyphen range bounds need a major version: {low} - {high}")
    primitives = [_Primitive(">=", _complete(low_nums, low_full))]
    if high_full is not None:
        primitives.append(_Primitive("<=", high_full))
    else:
        primitives.append(_Primitive("<", _bump(high_nums, len(high_nums) - 1)))
    return primitives


def _parse_set(text: str) -> list[_Primitive]:
    tokens = text.split()
    if not tokens:
        raise RangeError("empty comparator set")
    if "-" in tokens:
        if len(tokens) != 3 or tokens[1] != "-":
            raise RangeError(f"malformed hyphen range: {text!r}")
        return _hyphen(tokens[0], tokens[2])
    primitives: list[_Primitive] = []
    for token in tokens:
        primitives.extend(_desugar(token))
    return primitives


def _parse_range(range_expr: str) -> list[list[_Primitive]]:
    if not range_expr.strip():
        return [[_Primitive(">=", _ZERO)]]
    return [_parse_set(side) for side in range_expr.split("||")]


def _holds(version: _Version, primitive: _Primitive) -> bool:
    return _COMPARE[primitive.op](_precedence(version), _precedence(primitive.version))


def _satisfies(version: _Version, comparator_set: list[_Primitive]) -> bool:
    if not all(_holds(version, p) for p in comparator_set):
        return False
    if not version.pre:
        return True
    return any(p.version.pre and p.version.core == version.core for p in comparator_set)


def max_satisfying(versions: list[str], range_expr: str) -> str | None:
    """Return the highest version in `versions` that satisfies `range_expr`."""
    sets = _parse_range(range_expr)
    best: str | None = None
    best_key: tuple | None = None
    for text in versions:
        version = _parse_version(text)
        if not any(_satisfies(version, s) for s in sets):
            continue
        key = _precedence(version)
        if best_key is None or key > best_key:
            best, best_key = text, key
    return best
